from decimal import Decimal, ROUND_HALF_UP
import pytest

def comissao(valor: str) -> Decimal:
    base = Decimal(valor)
    if base < 0:
        raise ValueError("valor negativo")
    return (base * Decimal("0.02")).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )

@pytest.mark.parametrize("valor, esperado", [
    ("100", "2.00"), ("0.25", "0.01"), ("0", "0.00")
])
def test_comissao(valor, esperado):
    assert comissao(valor) == Decimal(esperado)

def test_negativo():
    with pytest.raises(ValueError, match="negativo"):
        comissao("-1")
